// src/Component/UserList.js
import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  fetchUsersAsync,
  selectUsersState,
  updateUserAsync,
  deleteUserAsync,
} from "./userSlice";
import "./UserList.css";

function UserList() {
  const dispatch = useDispatch();
  const { users, loading, error } = useSelector(selectUsersState);

  const [editUserId, setEditUserId] = useState(null);
  const [editData, setEditData] = useState({});
  const [newUserData, setNewUserData] = useState({
    username: "",
    email: "",
    first_name: "",
    last_name: "",
    profile: { bio: "", phone: "" },
    is_active: true,
  });

  const [currentPage, setCurrentPage] = useState(1);
  const usersPerPage = 5;

  useEffect(() => {
    dispatch(fetchUsersAsync());
  }, [dispatch]);

  // Pagination
  const indexOfLastUser = currentPage * usersPerPage;
  const indexOfFirstUser = indexOfLastUser - usersPerPage;
  const currentUsers = users.slice(indexOfFirstUser, indexOfLastUser);
  const totalPages = Math.ceil(users.length / usersPerPage);

  const handleChange = (key, value, isNew = false) => {
    if (key === "bio" || key === "phone") {
      if (isNew) {
        setNewUserData({
          ...newUserData,
          profile: { ...newUserData.profile, [key]: value },
        });
      } else {
        setEditData({
          ...editData,
          profile: { ...editData.profile, [key]: value },
        });
      }
    } else {
      if (isNew) {
        setNewUserData({ ...newUserData, [key]: value });
      } else {
        setEditData({ ...editData, [key]: value });
      }
    }
  };

  const handleSaveEdit = async () => {
    if (!editUserId) return;
    try {
      await dispatch(updateUserAsync(editData)).unwrap();
      await dispatch(fetchUsersAsync());
      setEditUserId(null);
      alert("✅ User updated successfully");
    } catch (err) {
      console.error(err);
      alert("Update failed");
    }
  };

  const handleDelete = async (id) => {
    if (!id) return;
    if (window.confirm("Are you sure you want to delete this user?")) {
      try {
        await dispatch(deleteUserAsync(id)).unwrap();
        await dispatch(fetchUsersAsync());
        alert("User deleted successfully!");
      } catch (err) {
        console.error(err);
        alert("Delete failed");
      }
    }
  };

  const handleAddUser = async () => {
    try {
      const token = localStorage.getItem("token");
      const payload = { ...newUserData };

      const res = await fetch("http://127.0.0.1:8000/api/users/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      if (!res.ok) throw new Error("Failed to add user");

      await dispatch(fetchUsersAsync());
      setNewUserData({
        username: "",
        email: "",
        first_name: "",
        last_name: "",
        profile: { bio: "", phone: "" },
        is_active: true,
      });
      alert("User added successfully!");
    } catch (err) {
      console.error(err);
      alert("Add user failed");
    }
  };

  if (loading) return <p>Loading users...</p>;
  if (error) return <p style={{ color: "red" }}>Error: {error}</p>;

  return (
    <div className="userlist-container">
      <h2>User Management</h2>

      {/* Add User Form */}
      <div className="add-user-form">
        <h3>Add New User</h3>
        <input
          type="text"
          placeholder="Username"
          value={newUserData.username}
          onChange={(e) => handleChange("username", e.target.value, true)}
        />
        <input
          type="text"
          placeholder="Email"
          value={newUserData.email}
          onChange={(e) => handleChange("email", e.target.value, true)}
        />
        <input
          type="text"
          placeholder="First Name"
          value={newUserData.first_name}
          onChange={(e) => handleChange("first_name", e.target.value, true)}
        />
        <input
          type="text"
          placeholder="Last Name"
          value={newUserData.last_name}
          onChange={(e) => handleChange("last_name", e.target.value, true)}
        />
        <input
          type="text"
          placeholder="Bio"
          value={newUserData.profile.bio}
          onChange={(e) => handleChange("bio", e.target.value, true)}
        />
        <input
          type="text"
          placeholder="Phone"
          value={newUserData.profile.phone}
          onChange={(e) => handleChange("phone", e.target.value, true)}
        />
        <select
          value={newUserData.is_active ? "Active" : "Inactive"}
          onChange={(e) =>
            handleChange("is_active", e.target.value === "Active", true)
          }
        >
          <option>Active</option>
          <option>Inactive</option>
        </select>
        <button onClick={handleAddUser}>Add User</button>
      </div>

      {/* Users Table */}
      <table className="user-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Username</th>
            <th>Email</th>
            <th>First Name</th>
            <th>Last Name</th>
            <th>Bio</th>
            <th>Phone</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {currentUsers.length > 0 ? (
            currentUsers.map((u) => (
              <tr key={u.id}>
                <td>{u.id}</td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.username || ""}
                      onChange={(e) => handleChange("username", e.target.value)}
                    />
                  ) : (
                    u.username
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.email || ""}
                      onChange={(e) => handleChange("email", e.target.value)}
                    />
                  ) : (
                    u.email
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.first_name || ""}
                      onChange={(e) => handleChange("first_name", e.target.value)}
                    />
                  ) : (
                    u.first_name
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.last_name || ""}
                      onChange={(e) => handleChange("last_name", e.target.value)}
                    />
                  ) : (
                    u.last_name
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.profile?.bio || ""}
                      onChange={(e) => handleChange("bio", e.target.value)}
                    />
                  ) : (
                    u.profile?.bio || ""
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.profile?.phone || ""}
                      onChange={(e) => handleChange("phone", e.target.value)}
                    />
                  ) : (
                    u.profile?.phone || ""
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <select
                      value={editData.is_active ? "Active" : "Inactive"}
                      onChange={(e) =>
                        handleChange("is_active", e.target.value === "Active")
                      }
                    >
                      <option>Active</option>
                      <option>Inactive</option>
                    </select>
                  ) : u.is_active ? (
                    "Active"
                  ) : (
                    "Inactive"
                  )}
                </td>
                <td>
                  <div className="actions-cell">
                    {editUserId === u.id ? (
                      <>
                        <button onClick={handleSaveEdit}>Save</button>
                        <button onClick={() => setEditUserId(null)}>Cancel</button>
                      </>
                    ) : (
                      <>
                        <button onClick={() => handleEditClick(u)}>Edit</button>
                        <button onClick={() => handleDelete(u.id)}>Delete</button>
                      </>
                    )}
                  </div>
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="9" style={{ textAlign: "center" }}>
                No users found
              </td>
            </tr>
          )}
        </tbody>
      </table>

      {/* Pagination */}
      <div className="pagination">
        {Array.from({ length: totalPages }, (_, i) => (
          <button
            key={i + 1}
            onClick={() => setCurrentPage(i + 1)}
            className={currentPage === i + 1 ? "active-page" : ""}
          >
            {i + 1}
          </button>
        ))}
      </div>
    </div>
  );
}

export default UserList;
